  "onl.ug.tamam": ["Tamam", "OK", "De acuerdo", "Certo", "حسنًا", "Хорошо"],
  "onl.ug.gerekce": ["Neden böyle oldu", "Why it went this way", "Por qué salió así", "Por que foi assim", "لماذا جرى هكذا", "Почему так вышло"],
  "onl.ug.belirleyen": ["Belirleyen: %1", "Decided by: %1", "Lo decidió: %1", "O que pesou: %1", "العامل الحاسم: %1", "Решило: %1"],
  "onl.ug.sonuc.kiskirt.basari": ["Kabul etti: ittifak sözü verdi.", "Agreed: an alliance pledge was given.", "Aceptó: dio su promesa de alianza.", "Aceitou: deu a promessa de aliança.", "قبِل: قطع عهد تحالف.", "Согласие: дан уговор о союзе."],
  "onl.ug.sonuc.kiskirt.ret": ["Reddetti; konu aranızda kaldı.", "Refused; the matter stays between you.", "Se negó; el asunto queda entre vosotros.", "Recusou; o assunto fica entre vocês.", "رفض؛ وبقي الأمر بينكما.", "Отказ; разговор остался между вами."],
  "onl.ug.sonuc.kiskirt.retHaber": ["Reddetti ve hedefe haber vereceğe benziyor.", "Refused, and seems likely to warn the target.", "Se negó y parece que avisará al objetivo.", "Recusou e parece que vai avisar o alvo.", "رفض ويبدو أنه سيخبر الهدف.", "Отказ, и, похоже, цель будет предупреждена."],
  "onl.ug.sonuc.katil.evet": ["Sözünü tuttu ve seninle hareket etti.", "Kept the pledge and acted with you.", "Cumplió la promesa y actuó contigo.", "Cumpriu a promessa e agiu com você.", "وفى بالعهد وتحرّك معك.", "Уговор сдержан: действовали вместе."],
  "onl.ug.sonuc.katil.hayir": ["Bu sefer çekindi; söz duruyor.", "Held back this time; the pledge still stands.", "Esta vez se contuvo; la promesa sigue en pie.", "Desta vez se conteve; a promessa continua de pé.", "تردّد هذه المرة؛ والعهد قائم.", "На этот раз — воздержание; уговор в силе."],
  "onl.ug.sonuc.yakalandi": ["Yakalandı: hedef kimin adına yapıldığını öğrenecek.", "Caught: the target will learn on whose behalf it was done.", "Lo descubrieron: el objetivo sabrá por quién se hizo.", "Foi pego: o alvo vai saber em nome de quem foi feito.", "انكشف الأمر: سيعرف الهدف لصالح من جرى.", "Попались: цель узнает, по чьей воле это сделано."],
  "onl.ug.sonuc.sozBoz": ["Söz bozuldu.", "The pledge is broken.", "La promesa se rompió.", "A promessa foi quebrada.", "نُقض العهد.", "Уговор нарушен."],
  "onl.ug.sonuc.araciIste": ["İsteğin arabulucuya ulaştı.", "Your request reached the mediator.", "Tu petición llegó al mediador.", "Seu pedido chegou ao mediador.", "وصل طلبك إلى الوسيط.", "Просьба дошла до посредника."],
  "onl.ug.sonuc.araciKapat": ["İstek kapandı; emanet geri döndü.", "The request is closed; anything held in trust was returned.", "La petición se cerró; el depósito se devolvió.", "O pedido foi encerrado; o depósito foi devolvido.", "أُغلق الطلب وأُعيدت الأمانة.", "Просьба закрыта; залог возвращён."],
  "onl.ug.sonuc.arabulucu.baris": ["Barıştırdın.", "Peace is made.", "Lograste la paz.", "A paz foi feita.", "تمّ الصلح.", "Мир заключён."],
  "onl.ug.sonuc.arabulucu.sartli": ["Şartlı barış: bir bedel ödenirse kırgınlık kalkacak.", "Conditional peace: the grudge lifts once a price is paid.", "Paz condicional: el rencor se irá si se paga un precio.", "Paz condicional: a mágoa passa quando um preço for pago.", "صلح مشروط: تزول الضغينة إن دُفع ثمن.", "Мир с условием: обида уйдёт, когда будет уплачена цена."],
  "onl.ug.sonuc.arabulucu.ateskes": ["Barış olmadı ama ateşkes sağlandı.", "No peace, but a truce was reached.", "No hubo paz, pero sí una tregua.", "Não houve paz, mas houve trégua.", "لم يتم الصلح لكن أُبرمت هدنة.", "Мира нет, но есть перемирие."],
  "onl.ug.sonuc.arabulucu.ret": ["Bu sefer olmadı.", "It did not work this time.", "Esta vez no funcionó.", "Desta vez não deu certo.", "لم ينجح هذه المرة.", "На этот раз не вышло."],
  "onl.ug.sonuc.arabulucu.gerekYok": ["Kırgınlık zaten kalmamış; istek kapandı.", "The grudge had already faded; the request is closed.", "El rencor ya había pasado; la petición se cerró.", "A mágoa já tinha passado; o pedido foi encerrado.", "كانت الضغينة قد زالت؛ أُغلق الطلب.", "Обида уже прошла; просьба закрыта."],
  "onl.ug.sonuc.sartOde": ["Şart ödendi; barış tamamlandı.", "The condition is paid; the peace is complete.", "La condición está pagada; la paz es completa.", "A condição foi paga; a paz está completa.", "دُفع الشرط واكتمل الصلح.", "Условие выполнено; мир полный."],
  "onl.ug.sonuc.casus": ["Anlaştınız; raporlar ay dönümünde gelir.", "Agreed; reports come at the month turn.", "Acordado; los informes llegan al cambiar el mes.", "Combinado; os relatórios chegam na virada do mês.", "تمّ الاتفاق؛ تصل التقارير مع تبدّل الشهر.", "Договорились; донесения придут на смене месяца."],
