  "onl.ug.etki.laf": ["Laf %1 kişiye ulaştı (ortalama güven %2).", "The talk reached %1 people (average trust %2).", "El rumor llegó a %1 personas (confianza media %2).", "O falatório chegou a %1 pessoas (confiança média %2).", "وصل الكلام إلى %1 أشخاص (متوسط الثقة %2).", "Слух дошёл до %1 чел. (среднее доверие %2)."],
  "onl.ug.etki.boykot": ["Boykot %1 ay sürecek.", "The boycott lasts %1 months.", "El boicot dura %1 meses.", "O boicote dura %1 meses.", "تدوم المقاطعة %1 أشهر.", "Бойкот продлится %1 мес."],
  "onl.ug.sart": ["Şart: %1 akçe ödenirse barış %2 olur · %3 ay içinde.", "Condition: if %1 akçe is paid, peace becomes %2 · within %3 months.", "Condición: si se pagan %1 akçe, la paz será %2 · en %3 meses.", "Condição: se %1 akçe forem pagos, a paz vira %2 · em %3 meses.", "الشرط: إن دُفعت %1 أقجة صار الصلح %2 · خلال %3 أشهر.", "Условие: при оплате %1 акче мир станет %2 · в течение %3 мес."],
