  // ---------------------------------------------------------------- üçgen olayları
  "onl.olay.ucgen.ihbar": ["%1 haber verdi: %2 onu sana karşı kazanmaya çalışmış.", "%1 warned you: %2 tried to turn them against you.", "%1 te avisó: %2 intentó ponerlo en tu contra.", "%1 avisou você: %2 tentou colocá-lo contra você.", "أخبرك %1: حاول %2 استمالته ضدك.", "%1 предупредил(а): %2 пытался настроить против тебя."],
  "onl.olay.ucgen.fark": ["%1 gördü: %2, %4 tarafında %3 ile gizlice konuştu.", "%1 saw it: %2 spoke secretly with %3 at the %4.", "%1 lo vio: %2 habló en secreto con %3 en %4.", "%1 viu: %2 falou em segredo com %3 em %4.", "رأى %1: تحدّث %2 سرًّا مع %3 عند %4.", "%1 видел(а): %2 тайно говорил(а) с %3 — место: %4."],
  "onl.olay.ucgen.yakalandi": ["%1, %2 adına sana karşı iş çevirirken yakalandı (%3).", "%1 was caught working against you on behalf of %2 (%3).", "%1 fue descubierto actuando contra ti en nombre de %2 (%3).", "%1 foi pego agindo contra você em nome de %2 (%3).", "انكشف %1 وهو يعمل ضدك لصالح %2 (%3).", "%1 попался(лась) на интриге против тебя по воле %2 (%3)."],
  "onl.olay.ucgen.ikiliOyun": ["%1 anlattı: arabulucun %2 onu daha önce sana karşı kışkırtmış.", "%1 revealed that your mediator %2 had earlier tried to turn them against you.", "%1 contó que tu mediador %2 antes intentó ponerlo en tu contra.", "%1 contou que seu mediador %2 antes tentou colocá-lo contra você.", "كشف %1 أن وسيطك %2 حاول سابقًا تحريضه ضدك.", "%1 рассказал(а): твой посредник %2 прежде настраивал против тебя."],
  "onl.olay.ucgen.araciTalebi": ["%1, %2 ile arasını bulmanı istiyor (%3).", "%1 asks you to make peace with %2 (%3).", "%1 te pide mediar con %2 (%3).", "%1 pede que você medeie com %2 (%3).", "يطلب %1 أن تصلح بينه وبين %2 (%3).", "%1 просит помирить с %2 (%3)."],
  "onl.olay.ucgen.araci.geri": ["%1 arabuluculuk isteğini geri çekti.", "%1 withdrew the mediation request.", "%1 retiró la petición de mediación.", "%1 retirou o pedido de mediação.", "سحب %1 طلب الوساطة.", "%1 отозвал(а) просьбу о посредничестве."],
  "onl.olay.ucgen.araci.ret": ["%1 arabuluculuk isteğini kabul edemedi.", "%1 could not take on the mediation.", "%1 no pudo aceptar la mediación.", "%1 não pôde aceitar a mediação.", "لم يستطع %1 قبول الوساطة.", "%1 не смог(ла) взяться за посредничество."],
  "onl.olay.ucgen.araci.dustu": ["Arabuluculuk isteğinin süresi doldu (%1).", "The mediation request expired (%1).", "La petición de mediación expiró (%1).", "O pedido de mediação expirou (%1).", "انتهت مدة طلب الوساطة (%1).", "Срок просьбы о посредничестве истёк (%1)."],
  "onl.olay.ucgen.arabuluculuk.baris": ["%1 seninle %2 arasını buldu: barıştınız (%3).", "%1 made peace between you and %2 (%3).", "%1 hizo las paces entre tú y %2 (%3).", "%1 fez as pazes entre você e %2 (%3).", "أصلح %1 بينك وبين %2 (%3).", "%1 помирил(а) тебя с %2 (%3)."],
  "onl.olay.ucgen.arabuluculuk.sartli": ["%1 araya girdi: %2 bir bedel karşılığında barışmaya razı.", "%1 stepped in: %2 will make peace for a price.", "%1 intervino: %2 hará las paces a cambio de un precio.", "%1 intercedeu: %2 aceita a paz em troca de um preço.", "تدخّل %1: يقبل %2 الصلح مقابل ثمن.", "%1 вмешался(лась): %2 согласен(на) на мир за плату."],
  "onl.olay.ucgen.arabuluculuk.ateskes": ["%1 araya girdi: %2 ile bir süre ateşkes var.", "%1 stepped in: a truce with %2 holds for a while.", "%1 intervino: hay una tregua con %2 por un tiempo.", "%1 intercedeu: há uma trégua com %2 por um tempo.", "تدخّل %1: هدنة مع %2 لفترة.", "%1 вмешался(лась): с %2 на время перемирие."],
  "onl.olay.ucgen.arabuluculuk.ret": ["%1 araya girdi ama %2 bu sefer yumuşamadı.", "%1 stepped in, but %2 did not soften this time.", "%1 intervino, pero %2 no se ablandó esta vez.", "%1 intercedeu, mas %2 não amoleceu desta vez.", "تدخّل %1 لكن %2 لم يلِن هذه المرة.", "%1 вмешался(лась), но %2 на этот раз не смягчился(лась)."],
  "onl.olay.ucgen.barisildi": ["%1 ile %2, %3 aracılığıyla barıştı.", "%1 and %2 made peace through %3.", "%1 y %2 hicieron las paces gracias a %3.", "%1 e %2 fizeram as pazes por meio de %3.", "تصالح %1 و%2 بوساطة %3.", "%1 и %2 помирились при посредничестве %3."],
  "onl.olay.ucgen.casusRapor": ["%1 anlattı: %2, %4 tarafında %3 ile görüştü.", "%1 reports: %2 met %3 at the %4.", "%1 informa: %2 se vio con %3 en %4.", "%1 relata: %2 se encontrou com %3 em %4.", "يفيد %1: التقى %2 بـ%3 عند %4.", "%1 доносит: %2 встречался(лась) с %3 — место: %4."],
  "onl.olay.ucgen.casusRapor.dusuk": ["%1 anlattı ama emin değil: %2, %4 tarafında %3 ile görüşmüş olabilir.", "%1 reports, but is not sure: %2 may have met %3 at the %4.", "%1 informa sin estar seguro: %2 quizá se vio con %3 en %4.", "%1 relata sem certeza: %2 talvez tenha se encontrado com %3 em %4.", "يفيد %1 دون تأكد: ربما التقى %2 بـ%3 عند %4.", "%1 доносит, но не уверен(а): возможно, %2 встречался(лась) с %3 — место: %4."],
  "onl.olay.ucgen.casusBos": ["%1: %2 bu ay kimseyle görüşmedi.", "%1: %2 met no one this month.", "%1: %2 no se vio con nadie este mes.", "%1: %2 não se encontrou com ninguém este mês.", "%1: لم يلتقِ %2 بأحد هذا الشهر.", "%1: %2 в этом месяце ни с кем не встречался(лась)."],
  "onl.olay.ucgen.casusBitti": ["%1, %2'i izlemeyi bıraktı: %3.", "%1 stopped watching %2: %3.", "%1 dejó de vigilar a %2: %3.", "%1 parou de vigiar %2: %3.", "توقف %1 عن مراقبة %2: %3.", "%1 перестал(а) следить за %2: %3."],
  "onl.ug.casusNeden.sure": ["süre doldu", "time is up", "se acabó el plazo", "o prazo acabou", "انتهت المدة", "срок вышел"],
  "onl.ug.casusNeden.birakti": ["izlenene bağlı çıktı", "turned out loyal to the watched", "resultó leal al vigilado", "revelou-se leal ao vigiado", "تبيّن أنه موالٍ للمراقَب", "оказался(лась) верен(на) наблюдаемому"],
  "onl.ug.casusNeden.farkedildi": ["fark edildi", "was noticed", "fue descubierto", "foi notado", "انكشف", "был(а) замечен(а)"],
  "onl.olay.ucgen.casusIhbar": ["%1 itiraf etti: %2 onu seni izlemesi için tutmuştu.", "%1 confessed that %2 had hired them to watch you.", "%1 confesó que %2 lo había contratado para vigilarte.", "%1 confessou que %2 o contratou para vigiar você.", "اعترف %1 بأن %2 استأجره لمراقبتك.", "%1 признался(лась): %2 нанял(а) следить за тобой."],
  "onl.olay.ucgen.casusFark": ["%1 fark etti: %2, %3 tarafında seni izliyordu.", "%1 noticed that %2 was watching you at the %3.", "%1 notó que %2 te vigilaba en %3.", "%1 notou que %2 vigiava você em %3.", "لاحظ %1 أن %2 كان يراقبك عند %3.", "%1 заметил(а): %2 следил(а) за тобой — место: %3."],

