  "onl.dn.gosterge.gonul": ["Gönül", "Spirit", "Ánimo", "Ânimo", "المعنويات", "Дух"],
  "onl.dn.toparlanir": ["Ayda +%1 toparlanır.", "Recovers +%1 a month.", "Se recupera +%1 al mes.", "Recupera +%1 por mês.", "يتعافى +%1 شهريًا.", "Восстанавливается на +%1 в месяц."],
  "onl.dn.toparlanmaBekler": ["Bir yer bulununca toparlanmaya başlar.", "Starts recovering once a place is found.", "Empieza a recuperarse al encontrar lugar.", "Começa a se recuperar quando houver lugar.", "يبدأ بالتعافي عند إيجاد مأوى.", "Начнёт восстанавливаться, когда найдётся ночлег."],
  "onl.dn.taban": ["En düşük %1.", "Never below %1.", "Nunca menos de %1.", "Nunca abaixo de %1.", "لا يقل عن %1.", "Не ниже %1."],
  "onl.dn.denge": ["Kendiliğinden %1 düzeyine doğru dengelenir.", "Settles towards %1 on its own.", "Se equilibra solo hacia %1.", "Equilibra-se sozinho rumo a %1.", "يتوازن تلقائيًا نحو %1.", "Само выравнивается к %1."],
  "onl.dn.olanlar": ["Sen yokken", "While you were away", "Mientras no estabas", "Enquanto você esteve fora", "أثناء غيابك", "Пока тебя не было"],
  "onl.dn.olanYok": ["Barınmanla ilgili bir şey olmadı.", "Nothing happened with your lodging.", "No pasó nada con tu alojamiento.", "Nada aconteceu com sua hospedagem.", "لم يحدث شيء بشأن مأواك.", "С ночлегом ничего не произошло."],
