  // sunucu dönüş anahtarları (donus-ekrani.ts)
  "onl.donus.baslik.toparlan": ["Önce bir dam altı bulalım", "First, let's find a roof", "Primero, busquemos un techo", "Primeiro, vamos achar um teto", "لنجد سقفًا أولًا", "Сначала найдём крышу над головой"],
  "onl.donus.baslik.hosgeldin": ["Yeniden hoş geldin", "Welcome back", "Bienvenido de nuevo", "Bem-vindo de volta", "أهلًا بعودتك", "С возвращением"],
  "onl.donus.barinma.kapali": ["Bu yerleşimde barınma için bir şey gerekmiyor.", "Nothing is needed for lodging in this settlement.", "No hace falta nada de alojamiento en este asentamiento.", "Nada é necessário de hospedagem neste povoado.", "لا حاجة إلى شيء للإيواء في هذه البلدة.", "В этом поселении о ночлеге заботиться не нужно."],
  "onl.donus.barinma.konakli": ["Kalacak yerin hazır.", "Your place to stay is ready.", "Tu lugar está listo.", "Seu lugar está pronto.", "مأواك جاهز.", "Ночлег на месте."],
  "onl.donus.barinma.misafir": ["Misafirhanede yerin var; hakkın sürüyor.", "You have a guesthouse bed; your right still holds.", "Tienes cama en la casa de huéspedes; tu derecho sigue.", "Você tem leito na casa de hóspedes; seu direito continua.", "لك مكان في دار الضيافة وحقك قائم.", "Есть место в странноприимном доме; право ещё действует."],
  "onl.donus.barinma.uyari": ["Konaklaman bitti; bir yer bulmak için zaman var.", "Your stay has ended; there is still time to find a place.", "Tu estancia terminó; aún hay tiempo para buscar lugar.", "Sua estadia acabou; ainda há tempo para achar um lugar.", "انتهت إقامتك؛ ما زال هناك وقت لإيجاد مأوى.", "Ночлег закончился; ещё есть время найти место."],
  "onl.donus.barinma.evsiz": ["Bir süredir kalacak yerin yok; bu yüzden yorgun ve gönlün biraz düşük.", "You have had no place to stay for a while, so you are tired and your spirit is a little low.", "Llevas un tiempo sin lugar donde quedarte; por eso estás cansado y algo desanimado.", "Faz um tempo que você está sem lugar para ficar; por isso está cansado e um pouco desanimado.", "مضت مدة بلا مأوى، لذا التعب ظاهر والمعنويات منخفضة قليلًا.", "Какое-то время не было ночлега, поэтому есть усталость и дух немного упал."],
  "onl.donus.barinma.canKaybi": ["Uzun süredir açıktasın; can da azaldı. Bir yer bulunca hepsi toparlanır.", "You have been out in the open for long and health dropped too. Everything recovers once you find a place.", "Llevas mucho a la intemperie y también bajó la salud. Todo se recupera al encontrar lugar.", "Você está ao relento há muito tempo e a saúde também caiu. Tudo se recupera quando achar um lugar.", "طال البقاء في العراء ونقصت الصحة أيضًا. يتعافى كل شيء عند إيجاد مأوى.", "Долго под открытым небом — убавилось и здоровье. Всё восстановится, когда найдётся ночлег."],
  "onl.donus.toparlanma.konaklama": ["Konaklama bulunca zincir durur, unvan kalkar; kondisyon ve gönül olağan hızla toparlanır.", "Once lodging is found, the chain stops and the title lifts; stamina and spirit recover at the usual pace.", "Al encontrar alojamiento, la cadena se detiene y el título desaparece; resistencia y ánimo se recuperan a ritmo normal.", "Ao encontrar hospedagem, a cadeia para e o título some; disposição e ânimo se recuperam no ritmo normal.", "عند إيجاد مأوى تتوقف السلسلة ويزول اللقب، وتتعافى اللياقة والمعنويات بالوتيرة المعتادة.", "Когда найдётся ночлег, цепочка остановится и прозвище уйдёт; выносливость и дух восстановятся в обычном темпе."],
  "onl.donus.hal.can.saglam": ["sağlam", "sound", "sano", "são", "سليم", "крепко"],
  "onl.donus.hal.can.yarali": ["yaralı", "wounded", "herido", "ferido", "جريح", "ранен(а)"],
